-- 25_prompts_estado_inicial_desarrollo.sql
-- Script de migración para una base YA EN PRODUCCIÓN (no forma parte de schema.sql ni seed.sql).
--
-- Para qué sirve:
--   Lleva a staging y producción el estado de desarrollo del Generador de Prompts que el dueño armó y probó:
--   los formularios de «medalla» y «medalla_dorsal» (grupos, parámetros y reglas) y los 7 ajustes (encabezado, textos, límites,
--   formatos, contacto de ejemplo y marca de agua). Reemplaza a lo que dejan las migraciones anteriores (incluida
--   «prompts_medalla_inicial», que este script supera).
--
-- Qué cambia:
--   Por cada producto: si el entorno no lo tiene, se crea activo; se inserta una versión publicada nueva (número
--   siguiente, plantilla vacía) con el formulario de desarrollo y la publicada anterior pasa a «archivada». Los
--   borradores no se tocan.
--   Los ajustes se escriben con el valor de desarrollo: lo que un administrador haya editado en ese entorno se pisa.
--   Los recursos fijos entran INACTIVOS y SIN URL: cada entorno usa imágenes de su propio bucket de Supabase.
--   Después, en cada entorno, el administrador crea un borrador, pega la URL de cada recurso, lo activa y publica.
--
-- Idempotencia: si la publicada ya tiene exactamente este formulario (comparación binaria del JSON), no inserta
--   otra versión; los ajustes se reescriben con el mismo valor.
--
-- Cómo se aplica:
--   Automáticamente al iniciar el servidor en staging y producción; en desarrollo: npm run migrate.
--
-- Reversa (solo antes de que el administrador publique otra versión): borrar la publicada de cada producto y volver
--   a marcar como «publicada» la archivada de número mayor.
--     DELETE v FROM `prompt_producto_versiones` v JOIN `prompt_productos` p ON p.`id` = v.`producto_id`
--       WHERE p.`codigo` IN ('medalla', 'medalla_dorsal') AND v.`estado` = 'publicada';

SET NAMES utf8mb4;

-- Autor de lo que se crea: el administrador principal, o el primer usuario con rol Administrador.
SET @formularios_autor = COALESCE(
  (SELECT `id` FROM `usuarios` WHERE `email` = 'admin@grupopremia.com' LIMIT 1),
  (SELECT MIN(`id`) FROM `usuarios` WHERE `rol_id` = 1));

-- ---------- Medalla («medalla») ----------
SET @formulario_1 = '{"grupos": [{"clave": "general", "etiqueta": "Datos generales", "parametros": [{"tipo": "texto", "ayuda": "Nombre del evento o texto de la medalla", "clave": "evento", "etiqueta": "Evento", "max_largo": 150, "requerido": true}]}, {"clave": "color", "etiqueta": "Color", "parametros": [{"tipo": "opciones", "clave": "color_de_la_medalla", "defecto": "Plata", "etiqueta": "Color de la medalla", "opciones": [{"valor": "Plata", "etiqueta": "Plata Antiguo", "texto_prompt": "Plata Antiguo"}, {"valor": "Oro", "etiqueta": "Oro Antiguo", "texto_prompt": "Oro Antiguo"}, {"valor": "Bronce", "etiqueta": "Bronce Antiguo", "texto_prompt": "Bronce Antiguo"}], "requerido": true}]}, {"clave": "acabados", "etiqueta": "Forma y acabado", "parametros": [{"tipo": "opciones", "clave": "forma", "defecto": "circular", "etiqueta": "Forma", "opciones": [{"valor": "cuadrada", "etiqueta": "Cuadrada", "texto_prompt": "cuadrada"}, {"valor": "circular", "etiqueta": "Circular", "texto_prompt": "circular"}, {"valor": "irregular", "etiqueta": "Irregular", "texto_prompt": "de forma irregular"}, {"valor": "al corte", "etiqueta": "Al corte", "texto_prompt": "cuyo contorno sigue la silueta del logo del frente (el reverso es su espejo)"}], "requerido": true}, {"tipo": "si_no", "clave": "relieve", "defecto": true, "etiqueta": "Relieve"}, {"tipo": "si_no", "clave": "textura", "defecto": true, "etiqueta": "Textura"}]}, {"clave": "frente", "etiqueta": "Parte frontal", "parametros": [{"max": 4, "tipo": "imagenes", "clave": "frente_imagenes", "max_mb": 5, "etiqueta": "Imágenes del frente", "formatos": ["jpg", "png", "svg", "webp"], "requerido": false, "sugerencias": ["Logo del organizador", "Logo de patrocinador", "Imagen decorativa"], "ubicaciones": ["Centro", "Arriba", "Abajo", "Izquierda", "Derecha", "Toda la cara (fondo)"], "descripcion_requerida": true}, {"tipo": "texto_largo", "ayuda": "Separa cada frase con una coma", "clave": "frente_frases", "etiqueta": "Frases del frente", "separador": ","}, {"tipo": "texto_largo", "clave": "frente_indicaciones", "etiqueta": "Indicaciones de diseño del frente"}]}, {"clave": "trasera", "etiqueta": "Parte trasera", "parametros": [{"tipo": "si_no", "clave": "trasera_lisa", "defecto": false, "etiqueta": "Trasera lisa"}, {"max": 4, "tipo": "imagenes", "clave": "trasera_imagenes", "max_mb": 5, "etiqueta": "Imágenes de la parte trasera", "formatos": ["jpg", "png", "svg", "webp"], "requerido": false, "visible_si": {"igual": false, "parametro": "trasera_lisa"}, "sugerencias": ["Logo de patrocinador", "Ruta del recorrido", "Imagen decorativa"], "ubicaciones": ["Centro", "Arriba", "Abajo", "Izquierda", "Derecha", "Toda la cara (fondo)"], "descripcion_requerida": true}, {"tipo": "texto_largo", "ayuda": "Separa cada frase con una coma", "clave": "trasera_frases", "etiqueta": "Frases de la parte trasera", "separador": ",", "visible_si": {"igual": false, "parametro": "trasera_lisa"}}, {"tipo": "texto_largo", "clave": "trasera_indicaciones", "etiqueta": "Indicaciones de diseño de la parte trasera", "visible_si": {"igual": false, "parametro": "trasera_lisa"}}]}, {"clave": "afiche_oficial", "etiqueta": "Afiche Oficial", "parametros": [{"max": 1, "tipo": "imagenes", "clave": "afiche", "max_mb": 5, "etiqueta": "Afiche", "formatos": ["jpg", "png", "svg", "webp"], "requerido": false, "sugerencias": ["Afiche Oficial"]}]}, {"clave": "liston", "etiqueta": "Listón", "parametros": [{"max": 10, "tipo": "imagenes", "clave": "liston_imagenes", "max_mb": 5, "etiqueta": "Imágenes del listón", "formatos": ["jpg", "png", "svg", "webp"], "requerido": false, "descripcion_requerida": true}]}], "reglas": [{"clave": "bloque_01", "texto": "{{#si lista_imagenes}}IMÁGENES DE REFERENCIA{{/si}}\\n{{#si lista_imagenes}}Adjunté {{total_imagenes}} en este orden. Son elementos reales del cliente: reprodúcelos con la mayor fidelidad posible (formas, colores y letras) y no los reemplaces ni los reinventes.{{/si}}\\n{{lista_imagenes}}", "activo": true, "etiqueta": "Imagenes", "posicion": "inicio"}, {"clave": "bloque_03", "texto": "OBJETIVO\\nGenera UNA sola imagen horizontal en formato 16:9, con calidad de fotografía de producto profesional, que muestre una MEDALLA vista de frente (cara izquierda) y de reverso (cara derecha), una al lado de la otra y a la misma escala.\\n\\nIMPORTANTE\\n- El resultado es una MEDALLA, no una moneda, un trofeo ni una insignia.\\n- La medalla contiene exclusivamente los textos entre comillas y los elementos indicados en este mensaje; el resto de cada superficie queda sin textos, números ni símbolos.\\n- Escribe los textos exactamente como aparecen entre comillas.", "activo": true, "etiqueta": "Objetivo", "posicion": "inicio"}, {"clave": "bloque_04", "texto": "PRODUCTO\\nMedalla **{{forma}}**{{#si relieve}} con alto relieve 3D marcado{{/si}}{{#si textura}} y textura granulada fina{{/si}}.\\nTexto principal de la medalla (solo en el frente): \\"{{evento}}\\".", "activo": true, "etiqueta": "Producto", "posicion": "inicio"}, {"clave": "bloque_05", "texto": "FRENTE (cara izquierda): DISEÑO EXCLUSIVO DEL FRENTE\\n- El frente lleva ÚNICAMENTE los elementos de esta lista; nada de esto aparece en el reverso:\\n{{#si frente_imagenes}}- Coloca {{frente_imagenes}}.{{/si}}\\n{{#si frente_frases}}- Frases exactas, con esta ortografía: {{frente_frases}}.{{/si}}\\n{{#si frente_indicaciones}}- Indicaciones de diseño del frente: {{frente_indicaciones}}{{/si}}", "activo": true, "etiqueta": "Diseño exclusivo del frente", "posicion": "inicio"}, {"clave": "bloque_06", "texto": "REVERSO (cara derecha): DISEÑO EXCLUSIVO DEL REVERSO\\n- Silueta idéntica a la del frente (su espejo horizontal visto por detrás), con el mismo contorno, argolla y grosor. No cambies la forma.\\n- El frente y el reverso son dos diseños distintos e independientes: nada del diseño del frente aparece en el reverso, y nada del reverso aparece en el frente.\\n{{#si grupo_trasera_vacio}}- La superficie del reverso es totalmente lisa: metal sin imágenes, textos, grabados ni elementos decorativos.{{/si}}\\n{{#no grupo_trasera_vacio}}- El reverso lleva ÚNICAMENTE los elementos de esta lista cerrada; no agregues ningún otro elemento, texto, logo ni figura:{{/no}}\\n{{#si trasera_imagenes}}- Coloca {{trasera_imagenes}}.{{/si}}\\n{{#si trasera_frases}}- Frases exactas, con esta ortografía: {{trasera_frases}}.{{/si}}\\n{{#si trasera_indicaciones}}- Indicaciones de diseño del reverso: {{trasera_indicaciones}}{{/si}}\\n{{#no grupo_trasera_vacio}}- Si las indicaciones piden un diseño libre o arbitrario, resuélvelo solo con relieve decorativo abstracto (líneas, patrones geométricos o textura), sin textos, números, logos ni figuras reconocibles.{{/no}}", "activo": true, "etiqueta": "Diseño exclusivo del reverso", "posicion": "inicio"}, {"clave": "bloque_07", "texto": "LISTÓN\\n{{#si liston_imagenes}}- Usa {{liston_imagenes}} como motivo del listón, repetido a lo largo de la cinta.{{/si}}\\n{{#si afiche}}- El listón lleva un diseño de fondo que use los colores de {{afiche}}, el afiche oficial de la carrera.{{/si}}", "activo": true, "etiqueta": "Listón", "posicion": "inicio"}, {"clave": "bloque_08", "texto": "{{otros_parametros}}", "activo": true, "etiqueta": "Parámetros generados", "posicion": "inicio"}, {"clave": "bloque_09", "texto": "COMPOSICIÓN\\n- Vista frontal recta, a la altura de la cámara y sin perspectiva: las dos medallas del mismo tamaño, a la misma altura y cada una centrada en su mitad de la imagen, con margen libre alrededor.\\n- El listón de cada medalla sale de la argolla en dos tramos que suben en línea recta y se abren en V hasta el borde superior de la imagen, donde quedan cortados por el borde; el resto del listón queda fuera de la imagen.\\n- Iluminación suave de estudio, sombras suaves pegadas a la medalla y detalle nítido del relieve.\\n- El fondo de la imagen debe ser color blanco; con esto permitimos que la medalla resalte y se aprecien bien los colores.", "activo": true, "etiqueta": "Composición", "posicion": "inicio"}, {"clave": "bloque_10", "texto": "PIE DE LA IMAGEN\\n{{#si recurso_plantilla_base}}- Escribe en los espacios de la franja inferior de la plantilla, en texto blanco y uno debajo del otro:{{/si}}\\n{{#no recurso_plantilla_base}}- Al pie, una franja horizontal con los colores del rojo y negro, y en texto blanco apilado (uno debajo del otro):{{/no}}\\n{{asesor_nombre}}\\n{{#si asesor_telefono}}{{asesor_telefono}}{{/si}}\\n{{asesor_correo}}", "activo": true, "etiqueta": "Pie de la imagen", "posicion": "inicio"}], "recursos": [{"url": "", "clave": "plantilla_base", "activo": false, "etiqueta": "Plantilla base", "posicion": "inicio", "descripcion": "plantilla de la imagen final, con la franja inferior del diseño de la empresa, los espacios para los datos del asesor y el logo en la esquina superior derecha"}], "esquema_version": 1}';

-- El producto se crea (activo) solo si el entorno no lo tiene.
INSERT INTO `prompt_productos` (`codigo`, `nombre`, `descripcion`, `estado`, `creado_por`)
SELECT 'medalla', 'Medalla', 'Medalla de evento con frente, reverso y listón', 'activo', @formularios_autor
WHERE NOT EXISTS (SELECT 1 FROM `prompt_productos` WHERE `codigo` = 'medalla');

-- Versión publicada nueva (número siguiente) salvo que la publicada ya tenga exactamente este formulario.
INSERT INTO `prompt_producto_versiones` (`producto_id`, `numero`, `estado`, `esquema`, `plantilla`, `creado_por`, `publicado_en`)
SELECT p.`id`,
       (SELECT COALESCE(MAX(x.`numero`), 0) + 1 FROM `prompt_producto_versiones` x WHERE x.`producto_id` = p.`id`),
       'publicada', @formulario_1, '', p.`creado_por`, CURRENT_TIMESTAMP
FROM `prompt_productos` p
WHERE p.`codigo` = 'medalla'
  AND NOT EXISTS (SELECT 1 FROM `prompt_producto_versiones` v
                  WHERE v.`producto_id` = p.`id` AND v.`estado` = 'publicada'
                    AND CONVERT(CAST(v.`esquema` AS CHAR) USING utf8mb4) COLLATE utf8mb4_bin = @formulario_1 COLLATE utf8mb4_bin);

-- La publicada anterior pasa a archivada cuando ya existe otra publicada con número mayor.
UPDATE `prompt_producto_versiones` v
JOIN `prompt_productos` p ON p.`id` = v.`producto_id`
JOIN `prompt_producto_versiones` n ON n.`producto_id` = v.`producto_id` AND n.`estado` = 'publicada' AND n.`numero` > v.`numero`
SET v.`estado` = 'archivada'
WHERE p.`codigo` = 'medalla'
  AND v.`estado` = 'publicada';

-- ---------- Medalla y Dorsal («medalla_dorsal») ----------
SET @formulario_2 = '{"grupos": [{"clave": "medalla", "etiqueta": "Medalla", "parametros": [{"max": 1, "tipo": "imagenes", "clave": "imagen_de_la_medalla", "max_mb": 5, "etiqueta": "Imagen de la Medalla", "formatos": ["jpg", "png", "svg", "webp"], "requerido": true}]}, {"clave": "diseno", "etiqueta": "Diseño", "parametros": [{"max": 1, "tipo": "imagenes", "clave": "afiche_oficial", "max_mb": 5, "etiqueta": "Afiche oficial", "formatos": ["jpg", "png", "svg", "webp"], "requerido": true, "sugerencias": ["Afiche oficial"], "descripcion_requerida": true}, {"tipo": "si_no", "ayuda": "¿Desea incluir logos de los patrocinadores en el dorsal?", "clave": "incluir_patrocinadores", "defecto": false, "etiqueta": "Incluir patrocinadores", "requerido": true}, {"max": 10, "tipo": "imagenes", "ayuda": "Logos de los patrocionadores de la carrera", "clave": "patrocinadores", "max_mb": 5, "etiqueta": "Patrocinadores", "formatos": ["jpg", "png", "svg", "webp"], "requerido": false, "visible_si": {"igual": true, "parametro": "incluir_patrocinadores"}, "descripcion_requerida": true}, {"tipo": "si_no", "clave": "numero_aleatorio", "defecto": true, "etiqueta": "Número Aleatorio", "requerido": true}, {"tipo": "numero", "ayuda": "Número específico que desea que aparezca en el dorsal", "clave": "numero_del_dorsal", "etiqueta": "Número del Dorsal", "requerido": false, "visible_si": {"igual": false, "parametro": "numero_aleatorio"}}]}], "reglas": [{"clave": "imagenes", "texto": "{{#si lista_imagenes}}IMÁGENES DE REFERENCIA{{/si}}\\n{{#si lista_imagenes}}Adjunté {{total_imagenes}} en este orden. Son elementos reales del cliente: reprodúcelos con la mayor fidelidad posible (formas, colores y letras) y no los reemplaces ni los reinventes.{{/si}}\\n{{lista_imagenes}}", "activo": true, "etiqueta": "Imagenes", "posicion": "inicio"}, {"clave": "objetivo", "texto": "OBJETIVO\\nGenera UNA sola imagen horizontal en formato 16:9, con calidad de fotografía de producto profesional, que muestre una MEDALLA vista de frente (izquierda) y un DORSAL (derecha), uno al lado del otro.\\n\\nIMPORTANTE\\n- El resultado es una MEDALLA, no una moneda, un trofeo ni una insignia; y un DORSAL, no una camisa, gymbag.\\n- La medalla es EXACTAMENTE igual a la imagen de referencia.\\n- El diseño del DORSAL tiene que combinar EXCLUSIVAMENTE con los colores del listón y afiche oficial.", "activo": true, "etiqueta": "Objetivo", "posicion": "inicio"}, {"clave": "diseno_dorsal", "texto": "DISEÑO\\nEl diseño del dorsal obligatoriamente tiene que combinar con el listón de la medalla. Para crear un diseño puedes apoyarte de tres recursos:\\n- {{imagen_de_la_medalla}}: Usa el diseño del listón y sigue el mismo patrón de colores.\\n{{#si numero_aleatorio}}- Usa un número aleatorio en el dorsal.{{/si}}\\n{{#no numero_aleatorio}}- Usa el número \\"{{numero_del_dorsal}}\\" en el dorsal.{{/no}}\\n{{#si incluir_patrocinadores}}- Incluye los logos de los patrocinadores ({{patrocinadores}}), únicamente en la parte superior e inferior del doral. Ajusta la altura de las imágenes, para que salgan completas dentro de cualquiera de las franjas.{{/si}}\\n\\nEl tamaño del dorsal es de 8.5\\" de ancho y 5.5\\" de alto. La proporción es rectangular.\\n\\nEl dorsal tiene que respetar una regla de tres franjas:\\n1. Diseño\\n2. Número con fondo blanco\\n3. Diseño\\nLas franjas 1 y 3 son las que diseñarás. La franja 2 tiene exclusivamente el número del dorsal y es ligeramente más alta; pero, el hecho que sea más alta no afecta a la proporción real del dorsal.\\n\\n", "activo": true, "etiqueta": "Diseño Dorsal", "posicion": "inicio"}, {"clave": "composicion", "texto": "COMPOSICIÓN\\n- Vista frontal recta, a la altura de la cámara y sin perspectiva: los dos productos, la medalla y el dorsal una centrada en su mitad de la imagen, con margen libre alrededor.\\n- Iluminación suave de estudio, sombras suaves pegadas a la medalla y dorsal; y detalle nítido del relieve únicamente de la medalla.\\n- El fondo de la imagen debe ser color blanco; con esto permitimos que los productos resalten y protagonizen los colores.", "activo": true, "etiqueta": "Composición", "posicion": "fin"}, {"clave": "pie_de_la_imagen", "texto": "PIE DE LA IMAGEN\\n{{#si recurso_plantilla_base}}- Escribe en los espacios de la franja inferior de la plantilla, en texto blanco y uno debajo del otro:{{/si}}\\n{{#no recurso_plantilla_base}}- Al pie, una franja horizontal con los colores del rojo y negro, y en texto blanco apilado (uno debajo del otro):{{/no}}\\n{{asesor_nombre}}\\n{{#si asesor_telefono}}{{asesor_telefono}}{{/si}}\\n{{asesor_correo}}", "activo": true, "etiqueta": "Pie de la imagen", "posicion": "inicio"}], "recursos": [{"url": "", "clave": "plantilla_base", "activo": false, "etiqueta": "Plantilla base", "posicion": "inicio", "descripcion": "Plantilla base"}], "esquema_version": 1}';

-- El producto se crea (activo) solo si el entorno no lo tiene.
INSERT INTO `prompt_productos` (`codigo`, `nombre`, `descripcion`, `estado`, `creado_por`)
SELECT 'medalla_dorsal', 'Medalla y Dorsal', 'Diseño de un dorsal acorde a una medalla', 'activo', @formularios_autor
WHERE NOT EXISTS (SELECT 1 FROM `prompt_productos` WHERE `codigo` = 'medalla_dorsal');

-- Versión publicada nueva (número siguiente) salvo que la publicada ya tenga exactamente este formulario.
INSERT INTO `prompt_producto_versiones` (`producto_id`, `numero`, `estado`, `esquema`, `plantilla`, `creado_por`, `publicado_en`)
SELECT p.`id`,
       (SELECT COALESCE(MAX(x.`numero`), 0) + 1 FROM `prompt_producto_versiones` x WHERE x.`producto_id` = p.`id`),
       'publicada', @formulario_2, '', p.`creado_por`, CURRENT_TIMESTAMP
FROM `prompt_productos` p
WHERE p.`codigo` = 'medalla_dorsal'
  AND NOT EXISTS (SELECT 1 FROM `prompt_producto_versiones` v
                  WHERE v.`producto_id` = p.`id` AND v.`estado` = 'publicada'
                    AND CONVERT(CAST(v.`esquema` AS CHAR) USING utf8mb4) COLLATE utf8mb4_bin = @formulario_2 COLLATE utf8mb4_bin);

-- La publicada anterior pasa a archivada cuando ya existe otra publicada con número mayor.
UPDATE `prompt_producto_versiones` v
JOIN `prompt_productos` p ON p.`id` = v.`producto_id`
JOIN `prompt_producto_versiones` n ON n.`producto_id` = v.`producto_id` AND n.`estado` = 'publicada' AND n.`numero` > v.`numero`
SET v.`estado` = 'archivada'
WHERE p.`codigo` = 'medalla_dorsal'
  AND v.`estado` = 'publicada';

-- ---------- Ajustes ----------

INSERT INTO `prompt_ajustes` (`clave`, `valor`, `descripcion`)
VALUES ('contacto_ejemplo', '{"correo": "asesor@grupopremia.com", "nombre": "Nombre Apellido", "telefono": "+123 5555 5555"}', 'Datos del asesor que se usan en la vista previa del administrador: nombre, correo y teléfono (el teléfono puede quedar vacío).')
ON DUPLICATE KEY UPDATE `valor` = VALUES(`valor`);

INSERT INTO `prompt_ajustes` (`clave`, `valor`, `descripcion`)
