VALUES ('formatos_imagen', '{"jpg": {"mime": "image/jpeg", "extensiones": ["jpg", "jpeg"]}, "png": {"mime": "image/png", "extensiones": ["png"]}, "svg": {"mime": "image/svg+xml", "extensiones": ["svg"]}, "webp": {"mime": "image/webp", "extensiones": ["webp"]}}', 'Formatos de imagen admitidos: por cada formato, sus extensiones de archivo y su tipo MIME.')
ON DUPLICATE KEY UPDATE `valor` = VALUES(`valor`);

INSERT INTO `prompt_ajustes` (`clave`, `valor`, `descripcion`)
VALUES ('limites', '{"reglas_max": 30, "recursos_max": 10, "separador_max": 5, "ubicacion_max": 40, "max_largo_tope": 5000, "recurso_max_mb": 8, "sugerencia_max": 60, "lista_max_items": 12, "regla_texto_max": 3000, "imagenes_mb_tope": 10, "imagen_nombre_max": 150, "imagenes_max_tope": 20, "recurso_timeout_ms": 10000, "regla_etiqueta_max": 80, "gemini_max_imagenes": 14, "imagenes_mb_defecto": 5, "plantilla_max_largo": 50000, "producto_nombre_max": 100, "imagenes_max_defecto": 3, "recurso_etiqueta_max": 80, "imagen_descripcion_max": 120, "recurso_descripcion_max": 300, "texto_max_largo_defecto": 150, "producto_descripcion_max": 255, "texto_largo_max_largo_defecto": 600}', 'Límites numéricos del módulo: largos de texto, cantidad y peso de imágenes, tamaños de producto, recursos fijos y tiempo de espera de lectura.')
ON DUPLICATE KEY UPDATE `valor` = VALUES(`valor`);

INSERT INTO `prompt_ajustes` (`clave`, `valor`, `descripcion`)
VALUES ('marca_de_agua', '{"color": "#1B2130", "texto": "GRUPO PREMIA", "angulo": -30, "escala": 0.3, "logo_url": "/assets/logos/LOGO_GP_isotipo.png", "opacidad": 0.15, "separacion": 1.5}', 'Marca de agua que el asesor aplica a una imagen: texto, logo (/assets/ o https del almacenamiento), opacidad, ángulo en grados, escala de la baldosa, separación entre baldosas y color hexadecimal del texto.')
ON DUPLICATE KEY UPDATE `valor` = VALUES(`valor`);

INSERT INTO `prompt_ajustes` (`clave`, `valor`, `descripcion`)
VALUES ('textos_asesor', '{"aviso_pegado": "Abre un chat nuevo en tu generador de imágenes y pega primero las imágenes, una por una y en este orden; al final pega el prompt.", "nota_prompt_nuevo": "Cada prompt es una instrucción nueva: la IA debe ignorar cualquier propuesta anterior. Pégalo en un chat nuevo.", "nota_orden_imagenes": "Se copian en orden. Pégalas una por una en el mismo mensaje de tu generador de imágenes.", "aviso_exceso_imagenes": "Gemini admite hasta {limite} imágenes de referencia y este pedido tiene {total}. Quita algunas imágenes para mejores resultados."}', 'Avisos y notas que el asesor ve al copiar las imágenes y el prompt. El aviso de exceso usa los marcadores {limite} y {total}.')
ON DUPLICATE KEY UPDATE `valor` = VALUES(`valor`);

INSERT INTO `prompt_ajustes` (`clave`, `valor`, `descripcion`)
VALUES ('textos_prompt', '{"no": "no", "si": "sí", "union": ", ", "total_uno": "{n} imagen", "imagen_ref": "imagen {numero}", "lista_linea": "- Imagen {numero} ({origen}): {descripcion}.{ubicacion}", "union_final": " e ", "extras_grupo": "{grupo}", "extras_linea": "- {etiqueta}: {valor}", "frases_union": ", ", "total_varios": "{n} imágenes", "detalle_union": "; ", "extras_titulo": "ESPECIFICACIONES ADICIONALES", "numero_unidad": "{valor} {unidad}", "frase_comillas": "\\"{frase}\\"", "imagen_detalle": " ({detalle})", "imagenes_intro": "Adjunté {total} en este orden. Son elementos reales del cliente: reprodúcelos con la mayor fidelidad posible (formas, colores y letras) y no los reemplaces ni los reinventes.", "imagenes_titulo": "IMÁGENES DE REFERENCIA", "lista_ubicacion": " Ubicación: {ubicacion}.", "detalle_ubicacion": "ubicación: {ubicacion}", "lista_sin_descripcion": "sin descripción"}', 'Frases que el sistema arma dentro del prompt (referencias a imágenes, lista numerada, totales, sí/no, comillas de frases, unidad y especificaciones adicionales). Los marcadores van entre llaves, por ejemplo {numero}.')
ON DUPLICATE KEY UPDATE `valor` = VALUES(`valor`);
